script:
(function () {
  'use strict';
  // Side-by-side fee comparison of up to three funds or accounts holding the same investment.
  // Simulated month by month for each option:
  //   each deposit (initial and monthly, end of month) is reduced by the front-end sales charge;
  //   each month the balance grows at (1 + r)^(1/12) - 1, the gross annual return, then the
  //   expense ratio / 12 and the advisory fee / 12 are deducted from the balance;
  //   each year end the flat account fee is deducted.
  // "No fees" runs the same plan with every fee at zero; cost of fees = no-fee value - ending value
  // (the fees themselves plus the growth they would have earned).
  // Return after fees is the money-weighted return (IRR of the deposits and the ending value),
  // annualized as (1 + monthly)^12 - 1.
  // Verified (Node, scratch tests): no fees, $10,000 at 7% for 20 years = 10,000 x 1.07^20 =
  // $38,696.84; 1% total ongoing fee on $10,000 at 0% for 1 year = 10,000 x (1 - 0.01/12)^12 =
  // $9,900.46; a 5% load on $10,000 at 0% leaves $9,500; $100/month for 12 months at 12.6825%
  // (1%/month) with no fees = $1,268.25 (annuity factor 12.6825); the after-fee return of a
  // no-fee plan equals the gross return; a $25 account fee for 4 years at 0% removes $100.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var KEYS = ['A', 'B', 'C'];

  // --- calc start
  function simulate(p, f) {
    var rm = Math.pow(1 + p.rate, 1 / 12) - 1;
    var bal = p.initial * (1 - f.load), plain = p.initial, invested = p.initial;
    var loads = p.initial * f.load, expenses = 0, advisory = 0, flat = 0, rows = [];
    var months = p.years * 12;
    for (var m = 1; m <= months; m++) {
      bal *= 1 + rm;
      plain *= 1 + rm;
      var e = Math.max(bal, 0) * f.expense / 12, a = Math.max(bal, 0) * f.advisory / 12;
      bal -= e + a;
      expenses += e;
      advisory += a;
      bal += p.monthly * (1 - f.load);
      loads += p.monthly * f.load;
      invested += p.monthly;
      plain += p.monthly;
      if (m % 12 === 0) {
        var fee = Math.min(f.flat, Math.max(bal, 0));
        bal -= fee;
        flat += fee;
        rows.push({ year: m / 12, invested: invested, balance: bal, plain: plain });
      }
    }
    return { ending: bal, plain: plain, invested: invested, loads: loads, expenses: expenses,
             advisory: advisory, flat: flat, fees: loads + expenses + advisory + flat, rows: rows };
  }

  // Money-weighted annual return: solves initial(1+i)^n + monthly * sum (1+i)^(n-t) = ending.
  function netAnnualReturn(initial, monthly, months, ending) {
    if (ending <= 0 || initial + monthly <= 0 || months < 1) return null;
    function fv(i) {
      var g = Math.pow(1 + i, months);
      return initial * g + monthly * (Math.abs(i) < 1e-12 ? months : (g - 1) / i);
    }
    var lo = -0.5, hi = 0.5;
    if (fv(lo) > ending || fv(hi) < ending) return null;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (fv(mid) < ending) lo = mid; else hi = mid;
    }
    return Math.pow(1 + (lo + hi) / 2, 12) - 1;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function setText(id, text) { document.getElementById(id).textContent = text; }
  function pct(v, digits) { return (v * 100).toFixed(digits === undefined ? 2 : digits) + '%'; }

  function update() {
    var p = { initial: num('cfInitial'), monthly: num('cfMonthly'), rate: num('cfReturn'), years: Math.round(num('cfYears')) };
    var useC = document.getElementById('cfUseC').checked;
    var keys = useC ? KEYS : KEYS.slice(0, 2);
    var opts = keys.map(function (k) {
      return { key: k, expense: num('cfExpense' + k), advisory: num('cfAdvisory' + k), load: num('cfLoad' + k), flat: num('cfFlat' + k) };
    });
    var error = document.getElementById('cfError');
    var bad = [p.initial, p.monthly, p.rate, p.years].some(isNaN) || p.initial < 0 || p.monthly < 0 ||
              p.initial + p.monthly <= 0 || p.rate < -50 || p.rate > 50 || p.years < 1 || p.years > 60;
    opts.forEach(function (o) {
      if ([o.expense, o.advisory, o.load, o.flat].some(isNaN) || o.expense < 0 || o.expense > 10 ||
          o.advisory < 0 || o.advisory > 10 || o.load < 0 || o.load > 10 || o.flat < 0) bad = true;
    });
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a starting amount or monthly addition, a return from -50% to 50%, 1 to 60 years, and fees from 0% to 10% (account fees of $0 or more).';
      return;
    }
    p.rate /= 100;
    var res = opts.map(function (o) {
      var r = simulate(p, { expense: o.expense / 100, advisory: o.advisory / 100, load: o.load / 100, flat: o.flat });
      r.key = o.key;
      r.ongoing = (o.expense + o.advisory) / 100;
      r.net = netAnnualReturn(p.initial, p.monthly, p.years * 12, r.ending);
      return r;
    });
    var best = res[0], worst = res[0];
    res.forEach(function (r) {
      if (r.ending > best.ending) best = r;
      if (r.ending < worst.ending) worst = r;
    });
    setText('cfBest', 'Option ' + best.key + ': ' + money.format(best.ending));
    setText('cfGap', money.format(best.ending - worst.ending));
    setText('cfNoFee', money.format(best.plain));
    setText('cfVerdict', best.ending - worst.ending < 0.5 ? 'The options end up with the same value.' :
      'After ' + p.years + ' years, option ' + best.key + ' ends ' + money.format(best.ending - worst.ending) +
      ' ahead of option ' + worst.key + ', which pays ' + money.format(worst.fees) + ' in fees against ' +
      money.format(best.fees) + '.');

    document.getElementById('cfHead').innerHTML = '<tr><th scope="col">Item</th>' +
      res.map(function (r) { return '<th scope="col">Option ' + r.key + '</th>'; }).join('') + '</tr>';
    var lines = [
      ['Ongoing fees per year', function (r) { return pct(r.ongoing); }],
      ['Ending value', function (r) { return money.format(r.ending); }],
      ['Total invested', function (r) { return money.format(r.invested); }],
      ['Sales charges', function (r) { return money.format(r.loads); }],
      ['Fund expenses', function (r) { return money.format(r.expenses); }],
      ['Advisory fees', function (r) { return money.format(r.advisory); }],
      ['Account fees', function (r) { return money.format(r.flat); }],
      ['Total fees paid', function (r) { return money.format(r.fees); }],
      ['Total cost of fees', function (r) { return money.format(r.plain - r.ending); }],
      ['Annual return after fees', function (r) { return r.net === null ? '–' : pct(r.net); }]
    ];
    document.getElementById('cfTable').innerHTML = lines.map(function (line) {
      return '<tr><th scope="row">' + line[0] + '</th>' + res.map(function (r) { return '<td>' + line[1](r) + '</td>'; }).join('') + '</tr>';
    }).join('');

    document.getElementById('cfYearHead').innerHTML = '<tr><th scope="col">Year</th><th scope="col">Invested</th><th scope="col">No fees</th>' +
      res.map(function (r) { return '<th scope="col">Option ' + r.key + '</th>'; }).join('') + '</tr>';
    document.getElementById('cfSchedule').innerHTML = res[0].rows.map(function (row, i) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.invested) + '</td><td>' + money.format(row.plain) + '</td>' +
        res.map(function (r) { return '<td>' + money.format(r.rows[i].balance) + '</td>'; }).join('') + '</tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cfForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
